CREATE TRIGGER players_record_stationary_time AFTER UPDATE OF x,y,area,channel ON players WHEN NEW.x != OLD.x OR NEW.y != OLD.y OR NEW.area != OLD.area OR NEW.channel != OLD.channel BEGIN UPDATE players SET last_movement_at_ms=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE id=NEW.id; END;
